1→use std::collections::{BTreeMap, BTreeSet};
use std::fs::File;
use std::io::Read;
use std::process::Command;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use anyhow::{Context, Result, bail, ensure};
use serde::{Deserialize, Serialize};
10→use serde_json::{Value, json};
use sha2::{Digest, Sha256};

const CAPTURE_BYTES: usize = 16 * 1024 * 1024;
const CAPTURE_NODES: usize = 512;
const CAPTURE_DEPTH: usize = 16;
const CAPTURE_TIMEOUT: Duration = Duration::from_secs(60);
const TOKEN_LIMIT: usize = 1024;
const CAPTURE_ROOT_PREFIX: &str = "/tmp/opdbus-threetched-capture-";

20→/// Explicit provenance for the only adaptation of native config schema output.
/// The disposable source directory itself is deliberately not sealed.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ConfigSchemaRelocation {
    pub rule: String,
    pub source: String,
    pub target_root: String,
    pub pointers: Vec<String>,
}
30→
fn canonical_config_root(path: &Path) -> Result<&str> {
    let text = path.to_str().context("threetched config root is not UTF-8")?;
    ensure!(text.starts_with('/') && text.len() <= 4096
        && !text.chars().any(char::is_control)
        && (text == "/" || text[1..].split('/').all(|part|
            !part.is_empty() && part != "." && part != "..")),
        "threetched config root must be an absolute canonical lexical path");
    Ok(text)
}
40→
fn pointer_child(parent: &str, key: &str) -> String {
    format!("{parent}/{}", key.replace('~', "~0").replace('/', "~1"))
}

fn default_strings<'a>(value: &'a Value, pointer: &str, strings: &mut BTreeMap<String, &'a str>) {
    match value {
        Value::String(text) => { strings.insert(pointer.to_owned(), text); }
        Value::Object(object) => {
            for (key, child) in object {
50→                default_strings(child, &pointer_child(pointer, key), strings);
            }
        }
        Value::Array(array) => {
            for (index, child) in array.iter().enumerate() {
                default_strings(child, &pointer_child(pointer, &index.to_string()), strings);
            }
        }
        _ => {}
    }
60→}

/// Visit defaults only at JSON Schema positions. Examples, extension data and
/// property names named `default` must not become accidental rewrite targets.
fn schema_default_strings<'a>(schema: &'a Value, pointer: &str, strings: &mut BTreeMap<String, &'a str>) {
    let Some(object) = schema.as_object() else { return; };
    if let Some(default) = object.get("default") {
        default_strings(default, &pointer_child(pointer, "default"), strings);
    }
    for keyword in ["$defs", "definitions", "properties", "patternProperties", "dependentSchemas", "dependencies"] {
70→        if let Some(children) = object.get(keyword).and_then(Value::as_object) {
            for (name, child) in children {
                schema_default_strings(child, &pointer_child(&pointer_child(pointer, keyword), name), strings);
            }
        }
    }
    for keyword in ["additionalProperties", "unevaluatedProperties", "propertyNames", "additionalItems",
        "unevaluatedItems", "contains", "not", "if", "then", "else", "contentSchema", "items"] {
        if let Some(child) = object.get(keyword) {
            let child_pointer = pointer_child(pointer, keyword);
80→            if keyword == "items" && child.is_array() {
                for (index, item) in child.as_array().expect("checked array").iter().enumerate() {
                    schema_default_strings(item, &pointer_child(&child_pointer, &index.to_string()), strings);
                }
            } else {
                schema_default_strings(child, &child_pointer, strings);
            }
        }
    }
    for keyword in ["allOf", "anyOf", "oneOf", "prefixItems"] {
90→        if let Some(children) = object.get(keyword).and_then(Value::as_array) {
            for (index, child) in children.iter().enumerate() {
                schema_default_strings(child, &pointer_child(&pointer_child(pointer, keyword), &index.to_string()), strings);
            }
        }
    }
}

fn path_suffix<'a>(value: &'a str, root: &str) -> Option<&'a str> {
    let suffix = value.strip_prefix(root)?;
100→    (suffix.is_empty() || suffix.starts_with('/') || root == "/").then_some(suffix)
}

fn relocate_config_defaults(schema: &mut Value, source: &Path, target: &Path) -> Result<ConfigSchemaRelocation> {
    let source = canonical_config_root(source)?;
    let target_root = canonical_config_root(target)?.to_owned();
    let mut strings = BTreeMap::new();
    schema_default_strings(schema, "", &mut strings);
    let replacements: Vec<_> = strings.into_iter().filter_map(|(pointer, text)| {
        path_suffix(text, source).map(|suffix| {
110→            let relocated = if target_root == "/" && suffix.starts_with('/') { suffix.to_owned() }
                else { format!("{target_root}{suffix}") };
            (pointer, relocated)
        })
    }).collect();
    let pointers = replacements.iter().map(|(pointer, _)| pointer.clone()).collect();
    for (pointer, text) in replacements {
        *schema.pointer_mut(&pointer).context("relocation pointer disappeared")? = Value::String(text);
    }
    let relocation = ConfigSchemaRelocation {
120→        rule: "config-root-defaults-v1".into(), source: "ZEROCLAW_CONFIG_DIR".into(), target_root, pointers,
    };
    relocation.validate(schema)?;
    Ok(relocation)
}

impl ConfigSchemaRelocation {
    fn validate(&self, schema: &Value) -> Result<()> {
        ensure!(self.rule == "config-root-defaults-v1" && self.source == "ZEROCLAW_CONFIG_DIR",
            "unsupported threetched config schema relocation");
130→        let target = canonical_config_root(Path::new(&self.target_root))?;
        ensure!(!target.contains(CAPTURE_ROOT_PREFIX), "threetched runtime root is a disposable capture path");
        ensure!(!serde_json::to_string(schema)?.contains(CAPTURE_ROOT_PREFIX),
            "threetched config schema leaks a disposable capture path");
        let mut strings = BTreeMap::new();
        schema_default_strings(schema, "", &mut strings);
        let mut previous: Option<&str> = None;
        for pointer in &self.pointers {
            ensure!(previous.is_none_or(|prior| prior < pointer.as_str()),
                "threetched relocation pointers are duplicated or unordered");
140→            previous = Some(pointer);
            let value = strings.get(pointer).context("threetched relocation pointer is not a string default")?;
            canonical_config_root(Path::new(value))?;
            ensure!(path_suffix(value, target).is_some(), "threetched relocated default is outside its declared root");
        }
        Ok(())
    }
}

/// Require an unmodified upstream build and complete source/binary provenance.
150→/// Golden preparation compares these digests to source.pin; runtime additionally
/// binds this manifest and executable to the sealed discovery descriptor.
pub fn validate_artifact_native_provenance(manifest: &Value) -> Result<()> {
    ensure!(manifest["format"] == "opdbus.threetched.v2"
        && manifest["source"]["mode"] == "unmodified-upstream"
        && manifest.get("patches").is_none(), "threetched requires unmodified upstream provenance");
    ensure!(manifest["artifact"]["name"] == "threetched"
        && manifest["artifact"]["upstream_binary"] == "zeroclaw"
        && manifest["artifact"]["rust_target"] == "x86_64-unknown-linux-gnu"
        && manifest["artifact"]["bytes"].as_u64().is_some_and(|bytes| bytes > 0),
160→        "invalid unmodified threetched artifact identity or native target");
    for key in [
        "/artifact/sha256", "/source/cargo_lock_sha256",
        "/upstream/source_archive_sha256", "/upstream/vendored_source_gzip_sha256",
    ] {
        ensure!(manifest.pointer(key).and_then(Value::as_str).is_some_and(|digest|
            digest.len() == 64 && digest.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))),
            "threetched artifact lacks valid {key} provenance");
    }
    ensure!(manifest["upstream"]["commit"].as_str().is_some_and(|commit|
170→        commit.len() == 40 && commit.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))),
        "threetched artifact lacks a pinned upstream commit");
    for key in ["/upstream/url", "/upstream/tag", "/toolchain/rustc", "/toolchain/cargo"] {
        ensure!(manifest.pointer(key).and_then(Value::as_str).is_some_and(|value| !value.is_empty()),
            "threetched artifact lacks {key}");
    }
    Ok(())
}

/// Complete threetched config schema plus a recursively discovered CLI token contract.
180→/// Token strings deliberately do not pretend to be threetched semantic value types.
#[derive(Debug, Clone)]
pub struct ThreetchedSurface {
    binary_path: PathBuf,
    binary_sha256: String,
    schema_bytes: Vec<u8>,
    schema_json: Value,
    schema_sha256: String,
    config_schema_relocation: Option<ConfigSchemaRelocation>,
    version: Option<String>,
190→    commands: BTreeMap<String, CommandSurface>,
}

/// Runtime-independent seal input. Executable paths are selected by the backend,
/// never trusted from a captured build artifact's location.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SurfaceSnapshot {
    pub format: String,
    pub binary_sha256: String,
200→    pub config_schema: String,
    pub config_schema_sha256: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub config_schema_relocation: Option<ConfigSchemaRelocation>,
    pub version: Option<String>,
    pub commands: BTreeMap<String, CapturedCommand>,
